import sys

def generate_town_prices(n):
    prices = [[0] * n for _ in range(n)]
    current_price = 1
    for i in range(n):
        for j in range(i + 1, n):
            prices[i][j] = current_price
            prices[j][i] = current_price
            current_price += 1
    return prices

def main():
    import sys
    n = int(sys.stdin.read().strip())
    prices = generate_town_prices(n)
    for row in prices:
        print(" ".join(map(str, row)))

if __name__ == "__main__":
    main()
